/**
 * GET /api/player/today-strength-default
 *
 * Read-time DEFAULT micro-dose for the player's Today card, generated by the
 * strength engine from the exercise library + MD templates — NO template table
 * required. This closes the gap where a team with neither a coach-sent session
 * nor its own custom programme (the shared microdose_templates table is only
 * populated for one club) would see no strength at all. Lite teams need only a
 * readiness check-in + week setup (MD context), which the engine already runs on.
 *
 * IMPORTANT — this is a DISPLAY fallback, not auto-send:
 *   - It does NOT persist anything (no player_today_strength_override write) and
 *     fires no push/message. It is only consulted by PlayerClient when every
 *     real source (coach-sent, custom programme, team template) came back empty.
 *   - The engine returns null on OFF / MD+2 / MD+3-rest days, and a rehab-only
 *     (empty) session for injured / RECOVERY players — both surface here as
 *     "no default" (structure: null), so strength never appears when it shouldn't.
 *   - "standard" mode: the clean squad MD template, readiness- and MD-tuned, with
 *     none of the per-player individualisation layers (which a bare Lite team has
 *     no data for anyway).
 *
 * Teams with the 09:00 automatic send in an individualised mode (B, 2026-11-18): for today this builds the SAME
 * session the send will build (`buildAutoSession`, one builder), so the card before 09:00 is a true preview, not a
 * different session that is swapped out at 09:00. `autoPreview: true` until 09:00 lets Today label it. Still
 * display-only: nothing persisted, no push, the Today layer order is unchanged (this stays the last fallback).
 *
 * Auth: player bearer token (same as the other /api/player routes).
 */

/** Iceland is on UTC: the 09:00 send is 09:00 UTC. */
const AUTO_SEND_AT = "09:00";

import { NextRequest, NextResponse } from "next/server";
import { getSupabaseAdmin } from "@/lib/supabase-admin";
import { requireAuthedPlayerId, getPlayerTeamId } from "@/lib/session-rpe/server";
import { loadPlayerStrengthSnapshot } from "@/lib/micropulse/strengthProgramming/loader";
import { buildStrengthSession } from "@/lib/micropulse/strengthProgramming";
import { strengthSessionToTodayStructure } from "@/lib/micropulse/strengthProgramming/toTodayStructure";
import { applyBlockToSession } from "@/lib/micropulse/strengthProgramming/blockEmphasis";
import { loadCoachStrengthRules } from "@/lib/micropulse/strengthProgramming/coachStrengthRules";
import { resolveCurrentBlock } from "@/lib/micropulse/strengthProgramming/resolveCurrentBlock";
import { buildAutoSession, loadAutoTeamContext } from "@/lib/micropulse/strengthProgramming/autoSession";
import { normalizeSendMode } from "@/lib/micropulse/strengthProgramming/sendMode";

export const runtime = "nodejs";

const todayIso = () => new Date().toISOString().slice(0, 10);

export async function GET(req: NextRequest) {
  try {
    const sb = getSupabaseAdmin();
    const { playerId } = await requireAuthedPlayerId(sb, req);
    const teamId = await getPlayerTeamId(sb, playerId);

    const url = new URL(req.url);
    const dayParam = url.searchParams.get("day");
    const day = dayParam && /^\d{4}-\d{2}-\d{2}$/.test(dayParam) ? dayParam : todayIso();
    const lang: "EN" | "IS" = String(url.searchParams.get("lang") ?? "").toUpperCase() === "IS" ? "IS" : "EN";

    // A default strength session is only legitimate with POSITIVE evidence of a
    // planned training day. With no week_plans row the MD engine would silently
    // default to MD-3 (a training day) and fabricate a session on an unplanned /
    // rest day. So require the row: absent ⇒ no_planned_day, explicit OFF ⇒ off_day
    // (both behave the same for the client — a neutral "no session" state).
    const { data: wp } = await sb
      .from("week_plans")
      .select("day_type")
      .eq("team_id", teamId)
      .eq("day_date", day)
      .maybeSingle();
    if (!wp) {
      return NextResponse.json({ ok: false, reason: "no_planned_day" });
    }
    const dayType = String((wp as { day_type?: string }).day_type ?? "").trim().toUpperCase();
    if (dayType === "OFF") {
      return NextResponse.json({ ok: false, reason: "off_day" });
    }

    // Automatic send on, individualised: preview exactly what 09:00 sends (and what a check-in rebuild builds).
    if (teamId && day === todayIso()) {
      const { data: team } = await sb.from("teams").select("strength_auto_send, strength_send_mode").eq("id", teamId).maybeSingle();
      const t = team as { strength_auto_send?: boolean | null; strength_send_mode?: string | null } | null;
      const mode = normalizeSendMode(t?.strength_send_mode);
      if (t?.strength_auto_send && mode !== "standard") {
        const [{ data: player }, ctx] = await Promise.all([
          sb.from("players").select("id, full_name").eq("id", playerId).maybeSingle(),
          loadAutoTeamContext(sb, { teamId, mode, todayIso: day, playerIds: [playerId] }),
        ]);
        const built = await buildAutoSession(sb, ctx, (player as { id: string; full_name: string | null } | null) ?? { id: playerId, full_name: null });
        if ("skip" in built) {
          // Injured / no strength today: the send skips this player too, so there is nothing to preview.
          return NextResponse.json({ ok: true, structure: null, reason: built.skip === "injured" ? "empty" : "no-session" });
        }
        const structure = strengthSessionToTodayStructure(built.session, lang);
        if (!structure.length) return NextResponse.json({ ok: true, structure: null, reason: "empty" });
        const s = built.session;
        return NextResponse.json({
          ok: true,
          structure,
          mdContext: s.mdContext,
          title: lang === "IS" ? "Áætlun þjálfarans" : "Your coach's plan",
          description: (lang === "IS" ? s.summaryIS : s.summaryEN) ?? null,
          summary: (lang === "IS" ? s.summaryIS : s.summaryEN) ?? null,
          durationMin: s.durationMin ?? null,
          autoPreview: new Date().toISOString().slice(11, 16) < AUTO_SEND_AT,
        });
      }
    }

    const snapshot = await loadPlayerStrengthSnapshot(sb, {
      playerId,
      teamId,
      todayIso: day,
      mdContextOverride: null, // auto MD from the (now-confirmed) week_plans row
    });

    // Standard mode = the clean squad MD template, still readiness/MD-tuned.
    let session = buildStrengthSession(snapshot, [], { mode: "standard" });
    if (!session) {
      // OFF / MD+2 / MD+3-rest — no strength day.
      return NextResponse.json({ ok: true, structure: null, reason: "no-session" });
    }

    // MESO layer: tilt the (already readiness/MD-tuned) session toward today's block and apply the
    // coach's authored block rule (scheme/%1RM/methods). Pure post-processor, applied AFTER the
    // readiness easing inside buildStrengthSession — mirrors the coach preview route. No team block /
    // no coach rule ⇒ unchanged. Display-only route: nothing is persisted.
    if (teamId) {
      const [coachRules, block] = await Promise.all([
        loadCoachStrengthRules(sb, teamId),
        resolveCurrentBlock(sb, teamId, day),
      ]);
      if (block) {
        session = applyBlockToSession(session, block.goalKey, block.phase, coachRules?.block?.[`${block.goalKey}:${block.phase}`], block.subPhase) ?? session;
      }
    }

    const structure = strengthSessionToTodayStructure(session, lang);
    if (!structure.length) {
      // Injured (rehab-only) or RECOVERY/HOLD (stripped) → nothing to show.
      return NextResponse.json({ ok: true, structure: null, reason: "empty" });
    }

    return NextResponse.json({
      ok: true,
      structure,
      mdContext: session.mdContext,
      title: lang === "IS" ? "Sjálfgefin styrktaræfing" : "Default strength session",
      description: (lang === "IS" ? session.summaryIS : session.summaryEN) ?? null,
      summary: (lang === "IS" ? session.summaryIS : session.summaryEN) ?? null,
      durationMin: session.durationMin ?? null,
    });
  } catch (e) {
    const msg = e instanceof Error ? e.message : "Unknown error";
    const status = msg === "Unauthorized" ? 401 : 500;
    return NextResponse.json({ ok: false, error: msg }, { status });
  }
}
